const integrationSources = `-- name: IntegrationSources :many
SELECT s.id, s.uuid, s.organization_id, s.object_type_id, s.path_template, s.identity_key, s.items_path, s.fields, s.enabled, s.created_at, s.updated_at, t.uuid AS object_type_uuid, t.key AS object_type_key, t.singular_label AS object_type_label
FROM integration_sources s JOIN custom_object_types t ON t.id = s.object_type_id AND t.organization_id = s.organization_id
WHERE s.organization_id = $1 AND t.archived_at IS NULL
ORDER BY t.singular_label
`

type IntegrationSourcesRow struct {
	ID              int64              `json:"id"`
	Uuid            uuid.UUID          `json:"uuid"`
	OrganizationID  int64              `json:"organization_id"`
	ObjectTypeID    int64              `json:"object_type_id"`
	PathTemplate    string             `json:"path_template"`
	IdentityKey     string             `json:"identity_key"`
	ItemsPath       string             `json:"items_path"`
	Fields          []byte             `json:"fields"`
	Enabled         bool               `json:"enabled"`
	CreatedAt       pgtype.Timestamptz `json:"created_at"`
	UpdatedAt       pgtype.Timestamptz `json:"updated_at"`
	ObjectTypeUuid  uuid.UUID          `json:"object_type_uuid"`
	ObjectTypeKey   string             `json:"object_type_key"`
	ObjectTypeLabel string             `json:"object_type_label"`
}

func (q *Queries) IntegrationSources(ctx context.Context, organizationID int64) ([]IntegrationSourcesRow, error) {
	rows, err := q.db.Query(ctx, integrationSources, organizationID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []IntegrationSourcesRow{}
	for rows.Next() {
		var i IntegrationSourcesRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.OrganizationID,
			&i.ObjectTypeID,
			&i.PathTemplate,
			&i.IdentityKey,
			&i.ItemsPath,
			&i.Fields,
			&i.Enabled,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ObjectTypeUuid,
			&i.ObjectTypeKey,
			&i.ObjectTypeLabel,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const integrationWidgetRejections = `-- name: IntegrationWidgetRejections :many
SELECT ci.uuid AS channel_uuid, ci.name AS channel_name, r.code, r.rejected_at
FROM widget_identity_rejections r JOIN channel_instances ci ON ci.id = r.channel_instance_id AND ci.organization_id = r.organization_id
WHERE r.organization_id = $1 ORDER BY r.rejected_at DESC LIMIT 10
`

